/**
 * Forward-compatible save loading/saving.
 *
 * Known fields are validated; unknown top-level fields and unknown fields
 * nested under `ext` are preserved verbatim through a load -> edit -> save
 * cycle (stable key order for known fields, unknowns appended in their
 * original order). Unknowns are stripped only when `strict: true`.
 */

/** Schema version this build understands. Newer MINOR versions load fine. */
export const SAVE_VERSION = 1;

const KNOWN_TOP_LEVEL = new Set(['version', 'gold', 'heroName', 'inventory', 'ext']);
const KNOWN_EXT = new Set(['cosmeticsVersion']);

export class SaveError extends Error {}

export interface SaveData {
  version: number;
  gold: number;
  heroName?: string;
  inventory?: string[];
}

export interface LoadOptions {
  /** When true, unknown top-level and `ext` fields are dropped. Default: false. */
  strict?: boolean;
}

export interface LoadedSave {
  data: SaveData;
  /** Reserialize the save, preserving any retained unknown fields. */
  serialize(): string;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function loadSave(text: string, opts: LoadOptions = {}): LoadedSave {
  let root: unknown;
  try {
    root = JSON.parse(text);
  } catch (e) {
    throw new SaveError(`save is not valid JSON: ${(e as Error).message}`);
  }
  if (!isPlainObject(root)) throw new SaveError('save root must be a JSON object');

  // --- validate known fields ---
  if (typeof root.version !== 'number' || !Number.isFinite(root.version) || root.version < 0) {
    throw new SaveError(`invalid "version": expected a non-negative number`);
  }
  // Forward compatibility: newer MINOR versions are fine to load. Only a
  // newer MAJOR version is rejected as unreadable.
  const [major] = String(root.version).split('.').map(Number);
  if (major > SAVE_VERSION) {
    throw new SaveError(
      `save major version ${major} is newer than supported ${SAVE_VERSION}; refusing to load`,
    );
  }
  if (typeof root.gold !== 'number' || !Number.isFinite(root.gold)) {
    throw new SaveError(`invalid "gold": expected a finite number`);
  }
  const data: SaveData = { version: root.version, gold: root.gold };
  if (root.heroName !== undefined) {
    if (typeof root.heroName !== 'string') throw new SaveError(`invalid "heroName": expected a string`);
    data.heroName = root.heroName;
  }
  if (root.inventory !== undefined) {
    if (!Array.isArray(root.inventory) || !root.inventory.every((x) => typeof x === 'string')) {
      throw new SaveError(`invalid "inventory": expected an array of strings`);
    }
    data.inventory = root.inventory;
  }

  const strict = opts.strict ?? false;
  const strictErr = (where: string, key: string): never => {
    throw new SaveError(`strict mode: unknown ${where} field "${key}"`);
  };

  // --- preserve unknown top-level fields, in original order ---
  const unknownTop: Array<[string, unknown]> = [];
  for (const [key, value] of Object.entries(root)) {
    if (KNOWN_TOP_LEVEL.has(key)) continue;
    if (strict) strictErr('top-level', key);
    unknownTop.push([key, value]);
  }

  // --- preserve unknown fields under ext, in original order ---
  const rawExt = root.ext;
  if (rawExt !== undefined && !isPlainObject(rawExt)) throw new SaveError(`invalid "ext": expected an object`);
  let knownExt: Record<string, unknown> | undefined;
  const unknownExt: Array<[string, unknown]> = [];
  if (isPlainObject(rawExt)) {
    for (const [key, value] of Object.entries(rawExt)) {
      if (KNOWN_EXT.has(key)) {
        (knownExt ??= {})[key] = value;
      } else {
        if (strict) strictErr('"ext"', key);
        unknownExt.push([key, value]);
      }
    }
  }

  return {
    data,
    serialize(): string {
      const out: Record<string, unknown> = {};
      // stable key order for known fields
      out.version = data.version;
      out.gold = data.gold;
      if (data.heroName !== undefined) out.heroName = data.heroName;
      if (data.inventory !== undefined) out.inventory = data.inventory;
      const extOut: Record<string, unknown> = {};
      if (knownExt) Object.assign(extOut, knownExt);
      for (const [k, v] of unknownExt) extOut[k] = v; // appended in original order
      if (Object.keys(extOut).length > 0) out.ext = extOut;
      for (const [k, v] of unknownTop) out[k] = v; // appended in original order
      return JSON.stringify(out, null, 2);
    },
  };
}

