import { describe, expect, it } from 'vitest';
import { loadSave, SaveError } from '../src/save';

const NEWER_SAVE = JSON.stringify({
  ext: { dlc2_pet: 'rock' },
  futureFlag: true,
  version: 1.3,
  gold: 250,
});

/** Pull a top-level key's serialized fragment out of a JSON document text. */
function fragmentOf(text: string, key: string): string {
  const root = JSON.parse(text) as Record<string, unknown>;
  if (!(key in root)) throw new Error(`key "${key}" missing`);
  return JSON.stringify(root[key]);
}

describe('forward-compatible saves', () => {
  it('keeps unknown fields byte-identical through load -> mutate -> save', () => {
    const save = loadSave(NEWER_SAVE);

    // edit a known field
    save.data.gold = 9999;

    const out = save.serialize();
    const parsed = JSON.parse(out) as Record<string, unknown>;

    // known field was mutated
    expect(parsed.gold).toBe(9999);
    // unknowns survived verbatim (byte-identical reserialization)
    expect(fragmentOf(out, 'futureFlag')).toBe(JSON.stringify(JSON.parse(NEWER_SAVE).futureFlag));
    expect(fragmentOf(out, 'ext')).toBe(JSON.stringify(JSON.parse(NEWER_SAVE).ext));
    expect((parsed.ext as Record<string, unknown>).dlc2_pet).toBe('rock');
  });

  it('serializes with stable key order for known fields, unknowns appended in original order', () => {
    // input order is scrambled on purpose
    const save = loadSave(NEWER_SAVE);
    const lines = save.serialize().split('\n').filter((l) => /^\s{2}"/.test(l)).map((l) => l.trim());
    expect(lines).toEqual([
      '"version": 1.3,',
      '"gold": 250,',
      '"ext": {',
      '"futureFlag": true',
    ]);
  });

  it('strips unknown fields only when strict: true', () => {
    const strict = loadSave(NEWER_SAVE, { strict: true });
    const parsed = JSON.parse(strict.serialize()) as Record<string, unknown>;
    expect(parsed).toEqual({ version: 1.3, gold: 250 });
    expect('futureFlag' in parsed).toBe(false);
    expect('ext' in parsed).toBe(false);
  });

  it('validates known fields', () => {
    expect(() => loadSave('{"version":"x"}')).toThrow(SaveError);
    expect(() => loadSave('{"version":1,"gold":"lots"}')).toThrow(SaveError);
    expect(() => loadSave('{"version":1,"gold":5,"inventory":[1]}')).toThrow(SaveError);
    expect(() => loadSave('[1,2]')).toThrow(SaveError);
    // newer MAJOR is rejected
    expect(() => loadSave('{"version":2,"gold":5}')).toThrow(/major version/);
  });
});

